import 'package:flutter/material.dart';import 'package:intl/intl.dart';import '../models/finance_models.dart';import '../services/database_service.dart';import '../services/finance_calculator.dart';import '../widgets/finance_ui.dart';
class ExpensesScreen extends StatefulWidget{const ExpensesScreen({super.key});@override State<ExpensesScreen> createState()=>_ExpensesScreenState();}
class _ExpensesScreenState extends State<ExpensesScreen>{
 List<ExpenseRecord> items=[];bool loading=true;String query='';String category='All';final search=TextEditingController();static const categories=['Rent','Utilities','Transport','Supplies','Maintenance','Salary-Monthly','Salary-Daily','Miscellaneous'];
 @override void initState(){super.initState();refresh();}@override void dispose(){search.dispose();super.dispose();}
 Future<void> refresh()async{final v=await DatabaseService.instance.expenses();if(mounted)setState(()=>{items=v,loading=false});}
 Future<void> edit([ExpenseRecord? old])async{final c=TextEditingController(text:old?.category??'Miscellaneous'),a=TextEditingController(text:old?.amount.toString()??''),d=TextEditingController(text:old?.description??'');DateTime date=old?.date??DateTime.now();final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,ss)=>AlertDialog(title:Text(old==null?'Add expense':'Edit expense'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(value:categories.contains(c.text)?c.text:'Miscellaneous',items:categories.map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>ss(()=>c.text=x??'Miscellaneous')),FinanceUi.amountField(a),TextField(controller:d,decoration:const InputDecoration(labelText:'Description')),TextButton.icon(onPressed:()async{final x=await showDatePicker(context:ctx,initialDate:date,firstDate:DateTime(2000),lastDate:DateTime(2100));if(x!=null)ss(()=>date=x);},icon:const Icon(Icons.calendar_month),label:Text(DateFormat('dd MMM yyyy').format(date)))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Save'))]))));final n=double.tryParse(a.text);if(ok==true&&n!=null&&n>0){final e=ExpenseRecord(id:old?.id,date:date,category:c.text,amount:n,description:d.text.trim());if(old==null){await DatabaseService.instance.addExpense(e);}else{await DatabaseService.instance.updateExpense(e);}await refresh();}c.dispose();a.dispose();d.dispose();}
 @override Widget build(BuildContext context){final shown=items.where((e)=>(category=='All'||e.category==category)&&('${e.category} ${e.description} ${e.amount}'.toLowerCase().contains(query.toLowerCase()))).toList();final total=shown.fold<double>(0,(s,e)=>s+e.amount);return Scaffold(appBar:AppBar(title:const Text('Expenses'),actions:[IconButton(onPressed:refresh,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>edit(),icon:const Icon(Icons.add),label:const Text('Add expense')),body:loading?const Center(child:CircularProgressIndicator()):Column(children:[Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:search,onChanged:(v)=>setState(()=>query=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search category or description')),const SizedBox(height:8),DropdownButtonFormField<String>(value:category,items:['All',...categories].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>setState(()=>category=x??'All')),Card(child:Padding(padding:const EdgeInsets.all(14),child:FinanceUi.row('Total shown (${shown.length})',total,bold:true)))])),Expanded(child:shown.isEmpty?FinanceUi.empty('No expense records yet'):ListView.builder(itemCount:shown.length,itemBuilder:(c,i){final e=shown[i];return ListTile(title:Text(e.description.isEmpty?e.category:e.description),subtitle:Text('${e.category} • ${DateFormat('dd MMM yyyy').format(e.date)}'),trailing:Text(FinanceCalculator.money(e.amount),style:const TextStyle(fontWeight:FontWeight.w700)),onTap:()=>edit(e),onLongPress:()async{if(await FinanceUi.confirm(c,'Delete this expense?')){await DatabaseService.instance.deleteExpense(e.id!);await refresh();}});} ))]));}
}
